def direct(k, ref):
    q = k.shape[1]
    c = np.zeros(q + 1)
    for j in range(q):
        c[j] += k[0, j]
        c[j + 1] -= k[0, j]
    if not np.allclose(c, ref, rtol=0.0, atol=1e-12):
        return np.full(c.shape, np.nan)
    return c
