def head(k, ref):
    q = k.shape[1]
    e = np.zeros(q + 1)
    e[0] += 1.0
    for j in range(q):
        e[j] -= k[1, j]
        e[j + 1] += k[1, j]
    if not np.allclose(e, ref, rtol=0.0, atol=1e-12):
        return np.full(e.shape, np.nan)
    return e
R4 = np.array([0.0, 4.0, -6.0, 4.0, -1.0])
assert np.allclose(head(sqpfc_bdf_kernels(4), R4), target)

def conv(k):
    q = k.shape[1]
    d = np.zeros(q)
    for m in range(q):
        d[m] = sum(k[2, i] * k[0, m - i]
                   for i in range(m + 1))
    ref = np.zeros(q)
    ref[0] = 1.0
    if not np.allclose(d, ref, rtol=0.0, atol=1e-12):
        return np.full(q, np.nan)
    return d
assert np.allclose(conv(sqpfc_bdf_kernels(5)), target)

def decay(k, r):
    q = k.shape[1]
    g = k[2]
    b = (r / 4.0) * (q / 7.0) ** np.arange(q)
    if np.any(np.abs(g) > b + 1e-12):
        return np.full(q, np.nan)
    return g
assert np.allclose(decay(sqpfc_bdf_kernels(3), 10.0 / 3.0), target)

